/bin/bash -lc "cat > /tmp/rsvp-check.cjs <<'EOF'
const { chromium } = require('/tmp/claude-0/-root-design/f13cfb4d-b71e-4ed8-960a-ee0a8c2a8818/scratchpad/pwnode/node_modules/playwright-core');
const assert = require('node:assert/strict');
(async () => {
  const browser = await chromium.launch({headless:true,executablePath:'/root/.cache/ms-playwright/chromium-1140/chrome-linux/chrome',args:['--no-sandbox','--no-zygote','--single-process','--headless=new']});
  const page = await browser.newPage();
  const errors = [];
  page.on('pageerror', e=> errors.push(e.message));
  await page.goto('file://' + process.cwd() + '/index.html');
  await page.evaluate(()=>document.fonts.ready);
  for (const width of [1440,768,375]) {
    await page.setViewportSize({width,height:1000});
    await page.screenshot({path:"'`/tmp/rsvp-${width}.png`,fullPage:true});
    assert.equal(await page.evaluate(()=>document.documentElement.scrollWidth > innerWidth),false, `Overflow at ${width}`);
    console.log(`Layout at ${width}px: no overflow`);
  }
  await page.locator('"'.submit').click();
  assert.equal(await page.locator('#name-error').isVisible(),true);
  await page.locator('#guest-name').fill('Alex Morgan');
  await page.locator('.submit').click();
  assert.equal(await page.locator('#attendance-error').isVisible(),true);
  await page.getByLabel('Joyfully accept').check();
  await page.locator('#guest-count').selectOption('2');
  await page.locator('#dietary').fill('One vegetarian; one peanut allergy.');
  await page.locator('.submit').click();
  assert.equal(await page.locator('#confirmation').isVisible(),true);
  assert.match(await page.locator('#response-summary').innerText(),/Alex Morgan/);
  assert.match(await page.locator('#response-summary').innerText(),/peanut allergy/);
  await page.getByRole('button',{name:'Edit my response'}).click();
  assert.equal(await page.locator('#guest-count').inputValue(),'2');
  await page.getByLabel('Regretfully decline').check();
  assert.equal(await page.locator('#attending-fields').isVisible(),false);
  await page.locator('.submit').click();
  assert.match(await page.locator('#response-summary').innerText(),/Regretfully declining/);
  assert.doesNotMatch(await page.locator('#response-summary').innerText(),/peanut allergy/);
  await page.reload();
  assert.equal(await page.locator('#guest-name').inputValue(),'Alex Morgan');
  assert.equal(await page.getByLabel('Regretfully decline').isChecked(),true);
  assert.equal(await page.locator('#attending-fields').isVisible(),false);
  assert.deepEqual(errors,[]);
  console.log('Validation, acceptance, decline, editing, persistence, and script errors: passed');
  await browser.close();
})();
EOF
node /tmp/rsvp-check.cjs"

